using System;
using System.Collections.Generic;
using UnityEngine;

namespace Framework.Grid
{
    /// <summary>
    /// 任意のデータ型を格納できる二次元グリッド管理クラス。
    /// 地形、アイテム、配置情報などの管理に使用する。
    /// </summary>
    /// <typeparam name="T">各マスに格納するデータ型</typeparam>
    public class GridMap<T>
    {
        #region Fields

        /// <summary>
        /// 各マスのデータを保持する二次元配列。
        /// </summary>
        private readonly T[,] cells;

        /// <summary>
        /// 上下左右の4方向を表す座標オフセット。
        /// </summary>
        private static readonly Vector2Int[] directions4 =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right
        };

        /// <summary>
        /// 上下左右と斜め方向を含む8方向の座標オフセット。
        /// </summary>
        private static readonly Vector2Int[] directions8 =
        {
            Vector2Int.up,
            Vector2Int.down,
            Vector2Int.left,
            Vector2Int.right,

            new Vector2Int( 1,  1),
            new Vector2Int(-1,  1),
            new Vector2Int( 1, -1),
            new Vector2Int(-1, -1)
        };

        #endregion

        #region Properties

        /// <summary>グリッドの横方向のマス数。</summary>
        public int Width { get; }

        /// <summary>グリッドの縦方向のマス数。</summary>
        public int Height { get; }

        /// <summary>グリッド全体のマス数。</summary>
        public int Count => cells.Length;

        /// <summary>グリッドの縦横サイズ。</summary>
        public Vector2Int Size => new Vector2Int(Width, Height);

        /// <summary>
        /// グリッドが占める座標範囲。
        /// 最大座標は範囲に含まれない。
        /// </summary>
        public RectInt Bounds => new RectInt(0, 0, Width, Height);

        #endregion

        #region Events

        /// <summary>
        /// マスのデータが変更された際に発生するイベント。
        /// 引数：変更座標、変更前のデータ、変更後のデータ。
        /// </summary>
        public event Action<Vector2Int, T, T> CellChanged;

        #endregion

        #region Constructors

        /// <summary>
        /// 指定されたサイズでグリッドを生成する。
        /// </summary>
        /// <param name="width">横方向のマス数</param>
        /// <param name="height">縦方向のマス数</param>
        /// <param name="initializer">
        /// 各マスの初期データを生成する処理。
        /// 未指定の場合はデータ型の既定値を使用する。
        /// </param>
        public GridMap(
            int width,
            int height,
            Func<Vector2Int, T> initializer = null)
        {
            // 不正なサイズでの生成を防止する。
            if (width <= 0)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(width),
                    "横幅は1以上である必要があります。");
            }

            if (height <= 0)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(height),
                    "縦幅は1以上である必要があります。");
            }

            Width = width;
            Height = height;

            // マスの格納領域を確保する。
            cells = new T[width, height];

            // 初期化処理が指定されている場合のみ実行する。
            if (initializer != null)
            {
                foreach (Vector2Int position in GetPositions())
                {
                    cells[position.x, position.y] =
                        initializer(position);
                }
            }
        }

        /// <summary>
        /// Vector2Intで指定されたサイズからグリッドを生成する。
        /// </summary>
        /// <param name="size">グリッドの縦横サイズ</param>
        /// <param name="initializer">各マスの初期化処理</param>
        public GridMap(
            Vector2Int size,
            Func<Vector2Int, T> initializer = null)
            : this(size.x, size.y, initializer)
        {
        }

        #endregion

        #region Indexers

        /// <summary>
        /// X座標とY座標を指定してマスのデータを取得・変更する。
        /// </summary>
        public T this[int x, int y]
        {
            get => GetCell(x, y);
            set => SetCell(x, y, value);
        }

        /// <summary>
        /// Vector2Intを指定してマスのデータを取得・変更する。
        /// </summary>
        public T this[Vector2Int position]
        {
            get => GetCell(position);
            set => SetCell(position, value);
        }

        #endregion

        #region Validation

        /// <summary>
        /// 指定された座標がグリッドの範囲内か判定する。
        /// </summary>
        /// <param name="x">判定対象のX座標</param>
        /// <param name="y">判定対象のY座標</param>
        /// <returns>範囲内の場合はtrue</returns>
        public bool IsInside(int x, int y)
        {
            return x >= 0 && x < Width &&
                   y >= 0 && y < Height;
        }

        /// <summary>
        /// 指定された座標がグリッドの範囲内か判定する。
        /// </summary>
        /// <param name="position">判定対象の座標</param>
        /// <returns>範囲内の場合はtrue</returns>
        public bool IsInside(Vector2Int position)
        {
            return IsInside(position.x, position.y);
        }

        #endregion

        #region Get Methods

        /// <summary>
        /// 指定された座標のマスデータを取得する。
        /// 範囲外の場合は例外を発生させる。
        /// </summary>
        /// <param name="position">取得対象の座標</param>
        /// <returns>指定座標のマスデータ</returns>
        public T GetCell(Vector2Int position)
        {
            ValidatePosition(position);

            return cells[position.x, position.y];
        }

        /// <summary>
        /// X座標とY座標を指定してマスデータを取得する。
        /// </summary>
        /// <param name="x">取得対象のX座標</param>
        /// <param name="y">取得対象のY座標</param>
        /// <returns>指定座標のマスデータ</returns>
        public T GetCell(int x, int y)
        {
            return GetCell(new Vector2Int(x, y));
        }

        /// <summary>
        /// 指定された座標のマスデータを安全に取得する。
        /// 範囲外の場合でも例外を発生させない。
        /// </summary>
        /// <param name="position">取得対象の座標</param>
        /// <param name="value">取得したマスデータ</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetCell(
            Vector2Int position,
            out T value)
        {
            if (!IsInside(position))
            {
                value = default(T);
                return false;
            }

            value = cells[position.x, position.y];

            return true;
        }

        /// <summary>
        /// X座標とY座標を指定して安全にデータを取得する。
        /// </summary>
        /// <param name="x">取得対象のX座標</param>
        /// <param name="y">取得対象のY座標</param>
        /// <param name="value">取得したマスデータ</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryGetCell(int x, int y, out T value)
        {
            return TryGetCell(new Vector2Int(x, y), out value);
        }

        #endregion

        #region Set Methods

        /// <summary>
        /// 指定された座標のマスデータを変更する。
        /// データが変更された場合はCellChangedを通知する。
        /// </summary>
        /// <param name="position">変更対象の座標</param>
        /// <param name="value">変更後のデータ</param>
        public void SetCell(Vector2Int position, T value)
        {
            ValidatePosition(position);

            // 変更前のデータを保持する。
            T previousValue = cells[position.x, position.y];

            // データが同一の場合は更新処理を行わない。
            if (EqualityComparer<T>.Default.Equals(
                previousValue, value))
            {
                return;
            }

            // 新しいデータを格納する。
            cells[position.x, position.y] = value;

            // 外部システムへ変更内容を通知する。
            CellChanged?.Invoke(position, previousValue, value);
        }

        /// <summary>
        /// X座標とY座標を指定してマスデータを変更する。
        /// </summary>
        /// <param name="x">変更対象のX座標</param>
        /// <param name="y">変更対象のY座標</param>
        /// <param name="value">変更後のデータ</param>
        public void SetCell(int x, int y, T value)
        {
            SetCell(new Vector2Int(x, y), value);
        }

        /// <summary>
        /// 指定された座標のマスデータを安全に変更する。
        /// </summary>
        /// <param name="position">変更対象の座標</param>
        /// <param name="value">変更後のデータ</param>
        /// <returns>座標が有効で処理できた場合はtrue</returns>
        public bool TrySetCell(Vector2Int position, T value)
        {
            if (!IsInside(position))
            {
                return false;
            }

            SetCell(position, value);

            return true;
        }

        /// <summary>
        /// 現在のマスデータを利用して新しいデータに更新する。
        /// </summary>
        /// <param name="position">更新対象の座標</param>
        /// <param name="updater">
        /// 現在のデータから更新後のデータを生成する処理
        /// </param>
        public void UpdateCell(
            Vector2Int position,
            Func<T, T> updater)
        {
            if (updater == null)
            {
                throw new ArgumentNullException(nameof(updater));
            }

            // 現在のデータを取得する。
            T currentValue = GetCell(position);

            // 更新処理から新しいデータを生成する。
            T newValue = updater(currentValue);

            SetCell(position, newValue);
        }

        #endregion

        #region Enumeration

        /// <summary>
        /// グリッド内のすべての座標を列挙する。
        /// </summary>
        /// <returns>グリッド内の全座標</returns>
        public IEnumerable<Vector2Int> GetPositions()
        {
            for (int y = 0; y < Height; y++)
            {
                for (int x = 0; x < Width; x++)
                {
                    yield return new Vector2Int(x, y);
                }
            }
        }

        /// <summary>
        /// 指定された座標に隣接するマスの座標を列挙する。
        /// グリッドの範囲外にある座標は除外する。
        /// </summary>
        /// <param name="position">基準となる座標</param>
        /// <param name="includeDiagonal">
        /// 斜め方向のマスを含める場合はtrue
        /// </param>
        /// <returns>隣接するマスの座標</returns>
        public IEnumerable<Vector2Int> GetNeighbors(
            Vector2Int position,
            bool includeDiagonal = false)
        {
            ValidatePosition(position);

            // 取得対象となる方向を選択する。
            Vector2Int[] directions =
                includeDiagonal ? directions8 : directions4;

            foreach (Vector2Int direction in directions)
            {
                // 基準座標から隣接座標を算出する。
                Vector2Int neighbor = position + direction;

                if (IsInside(neighbor))
                {
                    yield return neighbor;
                }
            }
        }

        /// <summary>
        /// 指定された条件に一致するマスの座標を列挙する。
        /// </summary>
        /// <param name="predicate">検索条件</param>
        /// <returns>条件に一致するマスの座標</returns>
        public IEnumerable<Vector2Int> FindPositions(
            Func<T, bool> predicate)
        {
            if (predicate == null)
            {
                throw new ArgumentNullException(nameof(predicate));
            }

            foreach (Vector2Int position in GetPositions())
            {
                if (predicate(GetCell(position)))
                {
                    yield return position;
                }
            }
        }

        /// <summary>
        /// 指定された条件に一致するマスの数を取得する。
        /// </summary>
        /// <param name="predicate">集計条件</param>
        /// <returns>条件に一致するマスの数</returns>
        public int CountCells(Func<T, bool> predicate)
        {
            if (predicate == null)
            {
                throw new ArgumentNullException(nameof(predicate));
            }

            // 条件に一致したマスの合計数。
            int count = 0;

            foreach (Vector2Int position in GetPositions())
            {
                if (predicate(GetCell(position)))
                {
                    count++;
                }
            }

            return count;
        }

        #endregion

        #region Bulk Operations

        /// <summary>
        /// 全マスを指定されたデータで埋める。
        /// </summary>
        /// <param name="value">各マスに設定するデータ</param>
        public void Fill(T value)
        {
            foreach (Vector2Int position in GetPositions())
            {
                SetCell(position, value);
            }
        }

        /// <summary>
        /// 全マスを指定された初期化処理で埋める。
        /// 座標ごとに異なるデータを設定できる。
        /// </summary>
        /// <param name="initializer">各マスの初期化処理</param>
        public void Fill(Func<Vector2Int, T> initializer)
        {
            if (initializer == null)
            {
                throw new ArgumentNullException(nameof(initializer));
            }

            foreach (Vector2Int position in GetPositions())
            {
                SetCell(position, initializer(position));
            }
        }

        /// <summary>
        /// 全マスをデータ型の既定値に戻す。
        /// </summary>
        public void Clear()
        {
            Fill(default(T));
        }

        #endregion

        #region Private Methods

        /// <summary>
        /// 指定された座標が有効であることを確認する。
        /// 範囲外の場合は例外を発生させる。
        /// </summary>
        /// <param name="position">確認対象の座標</param>
        private void ValidatePosition(Vector2Int position)
        {
            if (!IsInside(position))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(position),
                    $"座標 {position} はグリッドの範囲外です。");
            }
        }

        #endregion
    }
}
